{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Metoprolol, a polar beta-blocker with an ionizable amine, has mean systemic availability of 55% in young volunteers, directly supporting F>=20% for a polar/ionized query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfuzosin, a polar quinazoline with multiple H-bond donors/acceptors, has absolute oral bioavailability of 64.5% in healthy subjects, showing that high polarity does not preclude F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Benazeprilat, a highly polar dicarboxylic acid metabolite, has absolute bioavailability of 27.1-28.5%, just above the 20% threshold, supporting high for an ionized acidic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Atenolol, a polar beta-blocker with incomplete intestinal absorption, has oral bioavailability of 60-63% in humans, demonstrating that incompletely absorbed polar drugs can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, despite extensive first-pass metabolism, has absolute oral bioavailability of 32±7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Quinapril, an ester prodrug ACE inhibitor, has absolute bioavailability of 45.9% in healthy participants, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All highly transferable experimental analogues (F 27-90%) support oral bioavailability >=20%; the physicochemical prior of poor permeability is outweighed by direct human PK evidence from polar/ionized drugs.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "The query's sulfonylurea/acidic ionized motif is not exactly represented among the analogues, though polar/ionized drugs with F>=20 are.",
    "Transporter-mediated absorption and first-pass metabolism for the query are uncharacterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

